#ifndef APP_CMD_TABLE_H
#define APP_CMD_TABLE_H

#include "stack/ble/ble_common.h"

/**
 *  @brief  Compile-time switch for HCI command log.
 *          - 1: command name strings and log code are compiled in
 *          - 0: log code is stripped out, release build saves Flash
 *          User can override it in app_config.h before this header is included.
 */
#ifndef HCI_CMD_LOG_EN
#define HCI_CMD_LOG_EN 0
#endif

/**
 *  @brief  HCI OGF field values (the real 6-bit OGF field in bits 15..10 of the
 *          2-byte HCI command opcode). Note these are the real OGF field values,
 *          NOT the "OGF<<2" opcode bytes used by HCI_CMD_xxx_OPCODE_OGF macros
 *          in hci_const.h.
 */
#define HCI_OGF_LINK_CONTROL          0x01
#define HCI_OGF_LINK_POLICY           0x02
#define HCI_OGF_CONTROLLER_BASEBAND   0x03
#define HCI_OGF_INFORMATIONAL         0x04
#define HCI_OGF_STATUS_PARAMETERS     0x05
#define HCI_OGF_TESTING               0x06
#define HCI_OGF_LE_CONTROLLER         0x08
#define HCI_OGF_HIGHER_DATA_THROUGHPUT 0x3E
#define HCI_OGF_VENDOR                0x3F

/**
 *  @brief  Build the full 2-byte HCI command opcode from an OGF field value
 *          and an OCF value. OGF occupies bits 10-15 (6 bits), OCF occupies
 *          bits 0-9 (10 bits). All table opcodes MUST be generated with this
 *          macro, raw numbers are forbidden.
 */
#ifndef HCI_OPCODE_VALUE
#define HCI_OPCODE_VALUE(ogf, ocf) ((((u16)(ogf) & 0x3FU) << 10U) | ((u16)(ocf) & 0x03FFU))
#endif

/**
 *  @brief  HCI command handler signature.
 *  @param[in]  opcode  - full 2-byte HCI command opcode (built by HCI_OPCODE_VALUE)
 *  @param[in]  p_param - pointer to the first parameter byte of the command
 */
typedef void (*hci_cmd_handler_t)(u16 opcode, u8 *p_param);

/**
 *  @brief  One entry of an OCF sub-table (level 2).
 *          cmd_name is compiled out when HCI_CMD_LOG_EN == 0 to save Flash.
 */
#if (HCI_CMD_LOG_EN)
typedef struct
{
    u16               opcode;     //!< full 2-byte opcode, generated by HCI_OPCODE_VALUE()
    hci_cmd_handler_t handler;    //!< command handler
    const char       *cmd_name;   //!< command name string for log, stripped in release
} hci_ocf_cmd_t;
#else
typedef struct
{
    u16               opcode;     //!< full 2-byte opcode, generated by HCI_OPCODE_VALUE()
    hci_cmd_handler_t handler;    //!< command handler
} hci_ocf_cmd_t;
#endif

/**
 *  @brief  One group of the OGF top-level table (level 1): all commands with
 *          the same OGF. Each OCF sub-table is sorted by opcode ascending.
 */
typedef struct
{
    u8                   ogf;           //!< OGF field value, one of HCI_OGF_xxx
    const hci_ocf_cmd_t *ocf_sub_table; //!< OCF sub-table of this OGF group
    u16                  entry_cnt;     //!< entry count of the OCF sub-table
} hci_ogf_group_t;

/**
 *  @brief  Runtime switch for HCI command log, works together with HCI_CMD_LOG_EN.
 */
extern u8 hci_cmd_log_en;

/**
 *  @brief  Set/unset the runtime HCI command log switch.
 *  @param[in]  en - 1: enable log, 0: disable log
 */
void blc_hci_setCmdLogEnable(u8 en);

/**
 *  @brief  App owned HCI command tables (const, stored in Flash), defined in
 *          app_hci.c. Each OCF sub-table is one entry per command; the entries
 *          are gated by the APP_LE_* switches of app_config.h.
 */
extern const hci_ocf_cmd_t app_link_ctrl_ocf_table[];
extern const hci_ocf_cmd_t app_cbc_ocf_table[];
extern const hci_ocf_cmd_t app_ip_ocf_table[];
extern const hci_ocf_cmd_t app_sp_ocf_table[];
extern const hci_ocf_cmd_t app_le_ocf_table[];
#if (APP_LE_HDT_EN)
extern const hci_ocf_cmd_t app_hdt_ocf_table[];
#endif

extern const hci_ogf_group_t app_ogf_table[];

#endif /* APP_CMD_TABLE_H */
